,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'l_request_url varchar(32767);',
'l_content_type varchar(32767);',
'l_content_length varchar(32767);',
'l_filename varchar(32767);',
'l_response blob;',
'download_failed_exception exception;',
'BEGIN',
'l_request_url := ''https://natdcshjumpstartprod.objectstorage.us-ashburn-1.oci.customer-oci.com/n/natdcshjumpstartprod/b/bucket-20240514-1532/o/'' || apex_util.url_encode(:P3_filepath);',
